import { createElement, forwardRef } from 'react';
import { createLucideIcon, type LucideProps } from 'lucide-react';
import { SOLAR_COMPAT_DATA, type SolarUiName } from './compat-data.ts';

// Existing names and classes are API compatibility; all glyph artwork is Solar.
function solar(name: SolarUiName) {
  const Svg = createLucideIcon(name, SOLAR_COMPAT_DATA[name].nodes);
  const Component = forwardRef<SVGSVGElement, LucideProps>((props, ref) => {
    const attrs = { strokeWidth: 1.75, ...props, ref,
      style: props.color ? { color: props.color, ...props.style } : props.style,
      'data-solar-icon': name.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase() };
    return createElement(Svg, attrs);
  });
  Component.displayName = `Solar${name}`;
  return Component;
}

